-- Foetex.dk import (staging) - 35 rom (hverdagsrom)
-- Kilde: foetex.dk via Salling Groups offentlige Algolia-indeks (prod_FOETEX_PRODUCTS), 2026-11-08
-- Navne er bygget som brand + produktnavn (foetex bruger generiske navne som 'Hvid rom').
-- Havana Club 'Gylden rom' 37,5% og 45% er to forskellige produkter -> ABV i navnet.
-- Koer: 1) hele filen, 2) SELECT * FROM import_shop('Foetex', 'https://www.foetex.dk', 'stg_foetex_dk', 'Rom');

DROP TABLE IF EXISTS stg_foetex_dk;
CREATE TABLE stg_foetex_dk (
    name TEXT, url TEXT, price_dkk NUMERIC, in_stock BOOLEAN,
    volume_cl NUMERIC, abv NUMERIC, image_url TEXT, description TEXT,
    scraped_at TIMESTAMPTZ
);

-- Kontrol: forventer total=35, paa_lager=22, udsolgt=13, uden volumen/abv=0
SELECT COUNT(*) AS total,
       COUNT(*) FILTER (WHERE in_stock) AS paa_lager,
       COUNT(*) FILTER (WHERE NOT in_stock) AS udsolgt,
       COUNT(*) FILTER (WHERE volume_cl IS NULL) AS uden_volumen,
       COUNT(*) FILTER (WHERE abv IS NULL) AS uden_abv,
       MIN(price_dkk) AS billigste, MAX(price_dkk) AS dyreste
FROM stg_foetex_dk;
