INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Goslings Mørk rom', 'https://www.foetex.dk/produkter/moerk-rom/200189578/', 219, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/9606a8be5297e3e57d0a5f46642ca301', 'Black Seal Bermuda Black Rum fra Goslings er en afbalanceret mørk rom. Rommen bliver sammensat af sprit, der er destilleret på to slags pot stills. Den ene bruges til at destillere fin cognac, og den anden til grappa. Fra den ene destillering kommer der smag og den anden elegance. Black Seal Bermuda rommen passer især godt til drinken Dark ’n’ Stormy, hvor der blot skal tilføjes lidt rom, ginger beer, limesaft og isterninger og så er den klar til at blive serveret for dine gæster.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Reserva Exclusiva Rom', 'https://www.foetex.dk/produkter/reserva-exclusiva-rom/200097736/', 279, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/355a1b7093efdf782a1641ca49a61a39', 'Reserva Exclusiva Rom fra Diplomatico er en venezuelansk rom, der flere gange har været oppe at vende, som en af de bedste rom i verden. Reserva Exclusiva er en rom som smager af mere, og henvender sig til dig som er mest til den søde rom. Smagen er kompleks, sød og har noter af krydderier samt efterfulgt af en lang krydret eftersmag. Nyd Reserva Exclusiva Rom fra Diplomatico som den er en hyggelig aften i lænestolen eller find den frem, når dine gæster rigtig skal forkæles.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Mørk rom 7 år', 'https://www.foetex.dk/produkter/moerk-rom-7-aar/100289422/', 229, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/e3dc85d6-5914-4f04-8af8-14b55c4b38a8', 'Havana Club blev grundlagt i 1878 og er stadig den mest berømte cubanske rom. Rommen produceres stadig i Cuba, ved hjælp af de hæderkronede traditionelle teknikker og de fineste cubanske råmaterialer.<br><br>Takket være de cubanske Maestro Roneros (rom-mestre), har Havana Club bevaret det cubanske håndværk, det kræver for at opnå den perfekte destillation, aldring og blanding af de forskellige premium rom. Havana Club har gennem sin levetid fået tildelt medaljer ved de mest prestigefyldte internationale konkurrencer. Havana Club Añejo 7 Años er indbegrebet af cubansk rom. Nydes som den er eller med friskpresset citrus, der fremhæver smagsnuancerne eller i klassiske cocktails som for eksempel en old fashioned.<br><br><h2>Om Havana Club</h2><br>Havana Club er en hyldest til Cuba og cubansk kultur. Den cubanske romindustri begyndte for alvor at vokse i anden halvdel af det 19. århundrede og lige siden har cubansk rom været kendt og anerkendt verden over. Havana Club tilbyder en række forskellige romvarianter såsom Havana Club 3 års hvid rom eller romblandingen Pacto Navio blandt mange flere.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado 12 Års', 'https://www.foetex.dk/produkter/el-dorado-12-aars/200275494/', 423.68, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/97f0aac3f9ec16d2d60be6aa193c0132', '<b>Alkohol</b>: 40%<br><b>Indhold</b>: 70 cl.<br><b>Land</b>: Guyana<br>&nbsp;<br>El Dorado Demerara rom stammer fra det tidligere Britisk Guyana.&nbsp;Demerara var en af de oprindelige kolonier, der blev samlet til kolonien Britisk Guyana, som i dag hedder ”Guyana”. Demerara kolonien lå i området omkring Demerara floden og hovedbyen var Georgetown.<br>Demerara er i dag et af de tre distrikter i Guyana. De to andre er Berbice og Essequibo. Demerara er også fællesnavnet for en særlig type rå rørsukker, der ofte bruges til bagning og i kaffe.<br>El Dorado 12 har en duft af frodige, tropiske frugter og krydderier med strejf af honning og mørk sukker.<br>Den er fuld af karakter, og er perfekt afrundet med masser af sødme og fylde. Rige noter af frugt og krydderier, samt en dejlig, elegant og tør eftersmag.<br>Denne mørke El Dorado rom fra Guyana er det man forstår ved „rigtig rom“.<br>', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pampero Mørk rom Reserva Exclusiva', 'https://www.foetex.dk/produkter/moerk-rom-reserva-exclusiva/100289431/', 179, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/58ba5c15-a561-4a7f-add4-1812cb20f19c', '', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Puntacana Viejo rom', 'https://www.foetex.dk/produkter/puntacana-viejo-rom/200275480/', 270, FALSE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/1b748a2f5f62a412eb0972f08b0007e3', 'Puntacana Ron Viejo er en gylden rum med en smagfuld og fyldig karakter. Rommen er perfekt til at nyde rent i et cognacglas, men kan også anvendes i cocktails, hvor den giver en lækker og intens smag. Prøv eksempelvis at blande rommen med lidt frisk limejuice og sukker til en klassisk Daiquiri, eller mix den med ingefærøl og limejuice til en forfriskende Dark ''n'' Stormy.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Botran Mørk rom Reserva', 'https://www.foetex.dk/produkter/moerk-rom-reserva/100292077/', 229, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/f63086fe48e08b3dde65d9469ee9aefa', 'Botran Reserva Solera er en mørk rom fra Guatemala. Den har en fin mahogni farve med en lys gylden nuance. I næsen fornemmer man duften af nellike, kanel og muskatnød i et herligt mix med karamel. Den mørke rom har en kompleks smag af egetræsfad og en snert af vanilje samt noter af grønne æbler, tørrede tranebær, citronskal og appelsin. En forførende, tør og eksplosiv rom med en robust og moden smag. Nyd den som den er, med en isterning eller i en lækker cocktail.<br><br><h2>Om Botran</h2><br>I midten af det 20. århundrede slog fem brødre sig ned i Guatemala. Herfra har Ron Añejo Botran produceret rom igennem mere end seks årtier. Jordbunden i Guatemala er meget frugtbar og ideel til dyrkelse af hovedingrediensen i Botrans rom; sukkerrør. De lokale guatemalanske ressourcer kombineret med gamle europæiske traditioner som Solera modningssystemet er grundstenen i Botrans produktion af rom.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Soleima Hvid rom', 'https://www.foetex.dk/produkter/hvid-rom/200397602/', 99, TRUE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/b1fa9a1f562b6a820deb1c758efdd7a1', 'White Rum fra Soleima er en klar rom, der tilbyder en ren og let smag. Den er ideel til at lave mojito, pina colada eller daiquiri, hvor rommen er et godt match til de eksotiske smagsnoter.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Oliver Gylden rom', 'https://www.foetex.dk/produkter/gylden-rom/200397601/', 309, TRUE, 70, 38, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/e14cb3865cba64048402c1f02bee48e7', 'Punta Cana Tesoro fra Oliver &amp; Oliver er en rom med en velafbalanceret og fyldig smag. Den har en kompleks karakter, der gør den velegnet til både at nyde ren eller som en del af kreative cocktails. Server den ved stuetemperatur for at fremhæve den nuancerede smagsoplevelse.<br><br><h2>Om Oliver &amp; Oliver</h2><br>Oliver &amp; Oliver er en familieejet virksomhed med cubanske rødder, der har base i Den Dominikanske Republik. Producenten har specialiseret sig i fremstilling og markedsføring af håndlavede rom. De anvender en særlig metode inspireret af det traditionelle spanske solera-system, hvor nøje udvalgte sukkerrørsdestillater danner grundlaget for deres produktion. Sortimentet omfatter primært begrænsede og nummererede udgaver, som tappes og mærkes manuelt. Oliver &amp; Oliver har modtaget over 200 internationale priser for deres rom.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Puntacana Mørk rom', 'https://www.foetex.dk/produkter/moerk-rom/200397600/', 199, TRUE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/55334cad69fd361d4ba635ea9e1e0faf', 'Ron Muy Viejo fra Puntacana Club er en eksklusiv rom med en dyb og kompleks smagsprofil. Ron Muy Viejo betyder "meget gammel rom", og har fået sit navn, da det er en blanding af unge og ældre destillater blandet med en moder-rom, der har lagret i over 25 år. Denne blanding færdiglagres i 8-12 år, hvilket giver en meget afrundet smag af karamel og milde noter af egetræ. Nyd den som den er for at opleve de mange nuancer.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Barceló Barcelo Gran Añejo', 'https://www.foetex.dk/produkter/barcelo-gran-anejo/200397598/', 159, TRUE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/9f6aa7d2d2339b8379d8f49c95f25484', '<b>Indhold: </b>70 cl.<br><b>Alkohol: </b>37,5%<br><b>Land: </b>Den Dominikanske Republik<br>&nbsp;<br>Ron Barcelo Gran Anejo – en perfekt kombination af mange fine rom fra Den Dominikanske Republik.<br>Rommen er modnet på amerikanske egetræsfade. Disse egetræsfade har tidligere været brugt til bourbonlagring.<br>Ron Barcelo Gran Anejo byder på en særlig smag af karamel, kokosnød og et strejf af peber. Tilsammen skaber dette en yderst velsmagende rom og en fremragende aroma.<br>Duften er ligeledes særlig – en sødlig duft af karamel og nødder.<br>Barcelo og Co, som står bag denne rom, blev etableret i år 1930 og har gennemgået en markant udvikling siden da. Selskabet eksporterer i dag til 50 lande.<br>', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Oliver Gylden spiritus', 'https://www.foetex.dk/produkter/gylden-spiritus/200358718/', 299, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/62f362489d906efde3e7dc0537867be0', 'Gylden spiritus fra Oliver er en delikat drik, der kombinerer en rig smagsprofil med nuancer af karamel og vanilje. Den gyldne farve afslører en velafbalanceret sødme og en let krydret finish. Nyd den ren eller som en ingrediens i cocktails for at tilføje dybde og karakter til dine drinks.<br><br><h2>Om Oliver &amp; Oliver</h2><br>Oliver &amp; Oliver er en familieejet virksomhed med cubanske rødder, der har base i Den Dominikanske Republik. Producenten har specialiseret sig i fremstilling og markedsføring af håndlavede rom. De anvender en særlig metode inspireret af det traditionelle spanske solera-system, hvor nøje udvalgte sukkerrørsdestillater danner grundlaget for deres produktion. Sortimentet omfatter primært begrænsede og nummererede udgaver, som tappes og mærkes manuelt. Oliver &amp; Oliver har modtaget over 200 internationale priser for deres rom.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Gran Anejo', 'https://www.foetex.dk/produkter/gran-anejo/200267659/', 279, FALSE, 70, 42, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/7502e93cd27ea72c0fd43fe32254a500', 'Gran Anejo fra Plantation er en mørkgylden rom, der stammer fra Guatemala og Belize. Denne rom er kendt for sin komplekse smagsprofil med noter af karamel, vanilje og ristet kokos. Nyd den ren for at opleve de subtile nuancer som afslutning på et godt måltid.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Don Canarch Mørk rom', 'https://www.foetex.dk/produkter/moerk-rom/200217525/', 94.95, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/c5f39d18-cc43-4a6d-8872-59ebd412514b', 'Dark Rum fra Don Canarch er en let mørk rom, der er rig og harmonisk i smagen, og som har en delikat sødme. Rommen er ideel at anvende til lækre longdrinks eller cocktails – det vil garanteret imponere dine gæster.<br><br><h2>Om Don Canarch</h2><br>Don Canarch er navnet bag en serie af lyse og mørke rom for enhver smag. Sortimentet byder på både milde og tørre hvide rom, dybe og harmoniske mørke rom samt opblandede cocktails. Når du ønsker en god rom til en overkommelig pris, er Don Canarch det oplagte valg.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Don Canarch Hvid rom', 'https://www.foetex.dk/produkter/hvid-rom/200217524/', 94.95, TRUE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/8fc08983-630a-4166-a347-2ff89046af2a', 'White Rum fra Don Canarch er en let hvid rom, der er mild og tør i smagen og har en delikat sødme. Den er velegnet til cocktails som piña colada, strawberry daiquiri og mojito, hvor den tørre rom skaber et skønt samspil med de eksotiske frugter. <br><br><h2>Om Don Canarch</h2><br>Don Canarch er navnet bag en serie af lyse og mørke rom for enhver smag. Sortimentet byder på både milde og tørre hvide rom, dybe og harmoniske mørke rom samt opblandede cocktails. Når du ønsker en god rom til en overkommelig pris, er Don Canarch det oplagte valg.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Oliver & Oliver Mørk rom 12 år', 'https://www.foetex.dk/produkter/moerk-rom-12-aar/200163262/', 299, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/c682861b-b06d-4778-bac0-007d856747bb', 'Ron Quorhum Solera 12 fra Oliver &amp; Oliver har en blød smag, som er mere frugtagtig end mere traditionelle rom.<br><br><h2>Om producenten</h2><br>Oliver &amp; Oliver er en gammel virksomhed med rødder helt tilbage til midten af 1800-tallet. Den nyere historie går dog tilbage til 1997, hvor de siden har opkøbt rom i hele Caribien, som de selv lagrer. De har mere end 60 produkter, som sælges til mere end 18 lande.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Mantuano rom', 'https://www.foetex.dk/produkter/mantuano-rom/200129443/', 229, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/8fd0e2cb34f66504b21b36090186806d', 'Diplomático Mentuano er en mørk-gylden rom. Rommen har en dejlig duft af tørrede frugter, eg og krydderier, imens smagen giver noter af tørrede frugter og vanilje. Rommen er et blend af rom, der er destilleret på tre forskellige måder: 40% stammer fra Pot Stills, 20% fra Batch Kettle og 40% fra Column Stills. Rommen bliver lagret på egetræsfade i op til 8 år, der tidligere har været brugt til bourbon eller maltwhisky. Mentuano har en perfekt balance mellem det tunge, komplekse og lette og er skøn i sig selv, men også god i drinks.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Gylden rom 37,5%', 'https://www.foetex.dk/produkter/gylden-rom/100569132/', 149, TRUE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/c923ea0c9443ecd2a3ff83a3ea653e41', 'Havana Club Especial er en gylden rom. Den har en smuk, gylden kobberfarve og smagen er mild, tør og delikat. Rommen bliver dobbeltlagret på hvide egefade i op til fem år før den bliver filtreret gennem lag af trækul. Det resulterer i en rom med let sødme og med en klar hentydning vanilje. Havana Club Especial er oplagt i drinken Cuba Libre med cola og limesaft. Prøv den også med ginger beer og friske skiver af lime for en dejlig Dark ’n’ Stormy.  <br><br><h2>Om Havana Club</h2><br>Havana Club er en hyldest til Cuba og cubansk kultur. Den cubanske romindustri begyndte for alvor at vokse i anden halvdel af det 19. århundrede og lige siden har cubansk rom været kendt og anerkendt verden over. Havana Club tilbyder en række forskellige romvarianter såsom Havana Club 3 års hvid rom eller romblandingen Pacto Navio blandt mange flere.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bacardi Gylden rom 4 år', 'https://www.foetex.dk/produkter/gylden-rom-4-aar/100533630/', 179, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/36e25b43fb38c9d6c3d47fea1d0717b1', 'Gylden spiritus med milde vanilje- og honningnoter samt et strejf af ristet egetræ. Den perfekte spiritus til at mikse i drinks og cocktails.<br><br><h2>Om Bacardi</h2><br>Bacardi-familien har produceret spiritus siden 1862, hvor grundlæggeren Don Facundo Bacardi brugte over 10 år på at fremstille den perfekte Bacardi Carta Blanca. I dag tilbyder virksomheden et bredt udvalg af velsmagende spiritus i mange forfriskende smagsvarianter såsom hindbær, citron og kokos.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Gylden rom double aged Grande Reserve', 'https://www.foetex.dk/produkter/gylden-rom-double-aged-grande-reserve/100504405/', 249.95, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/d3b41008c1af1bb02a92878671b12291', '', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Gylden rom 23 Gran Reserva', 'https://www.foetex.dk/produkter/gylden-rom-23-gran-reserva/100289432/', 379, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/968ad25f5e71e87dd793861dff7c5a98', 'Ron Zapaca 23 er en rom med en kompleks og kraftig karakter. Smagen balancerer intense noter af muskat, tobak, eg og kaffe med krydrede noter af sød vanilje, kanel og ingefær – tilsammen giver det dig en delikat smagsoplevelse. Brug den i drinks og cocktails, som kan gøre enhver anledning lidt mere smagfuld og festlig.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Matusalem Gylden rom 15 år Gran Reserva', 'https://www.foetex.dk/produkter/gylden-rom-15-aar-gran-reserva/100289428/', 259.95, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/51a6edfc11119c7b52ba6e3da5a67166', 'Matusalem Gran Reserva Solera 15 er kendt som “the Cognac of Rums”. Denne rom er det perfekte valg, for dem der søger exceptionel kvalitet og udsøgt smag. Kompleks med en fløjlsblød og markant duft og smag. Matusalem Gran Reserva Solera 15 er en rom af højeste kvalitet og ideel til at at drikke rent eller on the rocks.<br><br>Farve: Dyb ravfarvet med rødlige toner og nuancer af okker.<br><br>Duft: En kompleks, raffineret og integreret duft med vedholdende noter af træ, der giver en intens og rig duft med toner af ristede nødder, karamel samt en forførende duft af vanilje, mørk farin, karamel, blommer og abrikoser.<br><br>Smag: Meget behagelig med blød konsistens, kompleks og med en vedvarende eftersmag med udtalte noter af egetræ samt tørrede tropiske frugter og en tør smag af fersken, nødder. Blød og intens fornemmelse af kakao med en elegant eftersmag af cognac.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pampero Gylden rom Resernva Madre', 'https://www.foetex.dk/produkter/gylden-rom-resernva-madre/100289427/', 179, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/5fb7bb3b-4249-48c6-98ae-0b72664f5a1e', '', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Hvid rom 3 år', 'https://www.foetex.dk/produkter/hvid-rom-3-aar/100289426/', 139.95, TRUE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/1289c10ff650427dae338dda19f87efa', 'Havana Club 3 Años rom er resultatet af en blanding af ældre og aromatiske sukkerrør, som efterfølgende har lagret på hvide egefade i tre år. Havana Club 3 Años er ideel at bruge, når du vil servere lækre cocktails og drinks for dig selv og dine gæster. Prøv for eksempel at lave en forfriskende Mojito eller smagfuld Daiquiri. <br>  <br><h2>Om Havana Club</h2><br>Havana Club er en hyldest til Cuba og cubansk kultur. Den cubanske romindustri begyndte for alvor at vokse i anden halvdel af det 19. århundrede og lige siden har cubansk rom været kendt og anerkendt verden over. Havana Club tilbyder en række forskellige romvarianter såsom Havana Club 3 års hvid rom eller romblandingen Pacto Navio blandt mange flere.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Captain Morgan Mørk rom', 'https://www.foetex.dk/produkter/moerk-rom/100289421/', 109, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/5692eb266ffa6b49e5295bc27e13d013', 'Captain Morgan Mørk Rom har en intens smag med et røget finish. Brug den mørke rom som mixer i smagfulde drinks. Lav for eksempel den velkendte drink Dark and Stormy serveret med frisk lime og isterninger, og servér den for dine gæster.<br><br><h2>Om Captain Morgan</h2><br>Hos Captain Morgan finder du et udvalg af smagfuld caribisk spiritus. Vælg blandt forskellige varianter som Spiced Gold, Tiki Mango Pineapple, White og Dark næste gang, du skal holde fest med gode venner.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bacardi Hvid rom', 'https://www.foetex.dk/produkter/hvid-rom/100289417/', 140, FALSE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/3e3f267e4c3e88259b005e6d15346e33', 'Bacardi Carta Blanca er en hvid rom. Den har en dejlig, velkendt smag og appellerer i høj grad til det festlige univers. Nyd den sammen med sukkersirup, mynte, lime, is og danskvand i en forfriskende mojito.<br><br><h2>Om Bacardi</h2><br>Bacardi-familien har produceret spiritus siden 1862, hvor grundlæggeren Don Facundo Bacardi brugte over 10 år på at fremstille den perfekte Bacardi Carta Blanca. I dag tilbyder virksomheden et bredt udvalg af velsmagende spiritus i mange forfriskende smagsvarianter såsom hindbær, citron og kokos.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Captain Morgan Hvid rom', 'https://www.foetex.dk/produkter/hvid-rom/100289353/', 109, TRUE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/ad7b3ccd-5801-4707-99f0-f3892974239d', 'Captain Morgan Hvid Rom er en caribisk rom med en krystalklar farve samt en blød og autentisk romsmag. Brug den søde rom i lækre cocktails, som egner sig perfekt til sommerhygge på altanen. Brug den for eksempel sammen med cola eller i en frisk Mojito med mynte og lime.<br><br><h2>Om Captain Morgan</h2><br>Hos Captain Morgan finder du et udvalg af smagfuld caribisk spiritus. Vælg blandt forskellige varianter som Spiced Gold, Tiki Mango Pineapple, White og Dark næste gang, du skal holde fest med gode venner.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hansen Gylden rom', 'https://www.foetex.dk/produkter/gylden-rom/100289232/', 144.95, TRUE, 70, 37.5, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/eaac93ac-806a-44bc-b588-3a4c463dd352', 'Danmarks 5. største rom hedder Hansen, og er trods navnet en rom fra Mellem- og Sydamerika. Den fremstilles af sukkerrør, og efter destilleringen lagres den på gamle egetræsfade. Her udvikler den særprægede og kraftige aroma sig til den harmoniske smag, som Hansen Golden Rum er kendt for.<br><br>Hansen Rum er velegnet som mixer til både varme og kolde drikke. Dette kunne være en Hansen Rum og varm kakao, eller med kold Cole, eller som ingrediens i en Mojito.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Gylden rom 45%', 'https://www.foetex.dk/produkter/gylden-rom/100289212/', 379, TRUE, 70, 45, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/562b5a87-6c08-4d38-8d9e-f60969cc4d7b', 'For at fremstille “Selección de Maestros” udvælger Maestros Roneros de bedste lagrede rom som derefter lagres på udvalgte egefade, hvorved den specielle karakter og intensitet udvikles. Når sidste lagring er færdig udvælges de bedste fade som udgør den endelige blanding. Denne specielle proces, the “Cuban Barrel Proof”, tilfører spiritus drikken sin helt særlige bouquet og fremragende kvalitet.<br><br><h2>Om Havana Club</h2><br>Havana Club er en hyldest til Cuba og cubansk kultur. Den cubanske romindustri begyndte for alvor at vokse i anden halvdel af det 19. århundrede og lige siden har cubansk rom været kendt og anerkendt verden over. Havana Club tilbyder en række forskellige romvarianter såsom Havana Club 3 års hvid rom eller romblandingen Pacto Navio blandt mange flere.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cucullo Rum Mørk rom Reserva', 'https://www.foetex.dk/produkter/moerk-rom-reserva/200275492/', 252.78, TRUE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/894fb135a569fede8f516ecbb008fae8', '12 Reserva fra Cucullo Rum er en rom med en intens og fyldig smag. Nyd den ren, eller brug den som ingrediens i dine yndlingscocktails.<br><br><h2>Om Cucullo Rum</h2><br>Cucullo Rum er opkaldt efter Cucullo ildfluen, som blev brugt som lys i lanterner og til at bekæmpe skadelige insekter på sukkerrørsmarkerne i Caribien i slutningen af 1920''erne. Ildfluerne vogtede flittigt over den dyrebare sukkerrørsafgrøde, som er selve grundlaget for deres romproduktion.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kaniché Perfeccion Rum', 'https://www.foetex.dk/produkter/perfeccion-rum/200092808/', 399, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/b847e000b29242f259b49001b88e637f', 'Kaniché Perfección er en mørk og fyldig rom, som er fadlagret i adskillige år. Rommen har et varmt, ravfarvet udseende, og duften har noter af ristet kokos, kakaopulver og smeltet sukker. Smagen er domineret af sødlig, tropisk frugt, som bliver afløst af kaffe, flødekaramel, vanilje og kardemomme i eftersmagen. Det anbefales, at rommen drikkes rent for den fulde romoplevelse. Kast dig ud i en spændende verden af rom, og prøv Kaniché Perfección til en aften i godt selskab.<br><br><h2>Om Kaniché Perfección</h2><br> Kaniché Perfección er en mellemamerikansk rom, nærmere bestemt fra Panama. Rommen bliver gæret på sukkerrørsmelasse og destilleret på kolonnekedler. Derefter lagrer den i mange år på bourbonfade i det tropiske klima, og får til sidst en efterlagring på cognacfade.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Oliver & Oliver Quorhum', 'https://www.foetex.dk/produkter/quorhum/200249471/', 349, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/6b4e5a6c38e4a03e2b4997184aac8509', 'Quorhum 12 fra Oliver &amp; Oliver er en mørkgylden rom fra Den Dominikanske Republik. Special Edition.<br><br><h2>Om producenten</h2><br>Oliver &amp; Oliver er en gammel virksomhed med rødder helt tilbage til midten af 1800-tallet. Den nyere historie går dog tilbage til 1997, hvor de siden har opkøbt rom i hele Caribien, som de selv lagrer. De har mere end 60 produkter, som sælges til mere end 18 lande.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bacardi Gylden rom 10 år Gran Reserva', 'https://www.foetex.dk/produkter/gylden-rom-10-aar-gran-reserva/200149657/', 370, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/162816f6c383ef6629efe3a06a2b9f9f', 'Gran Reserva Diez fra Bacardi er en gylden rom, som er fadlagret i mindst 10 år. Rommen er modnet i forkullede hvidegstønder for at opnå den gyldne farve og de diskrete noter af røg. Smagen er domineret af karamel, banan og ananas. Serveres ved stuetemperatur eller med isterninger. Nyd et glas Gran Reserva Diez fra Bacardi til en hyggelig kortaften eller andre festlige lejligheder. Prøv den også sammen med mørk chokolade.<br><br><h2>Om Bacardi</h2><br>Bacardi-familien har produceret spiritus siden 1862, hvor grundlæggeren Don Facundo Bacardi brugte over 10 år på at fremstille den perfekte Bacardi Carta Blanca. I dag tilbyder virksomheden et bredt udvalg af velsmagende spiritus i mange forfriskende smagsvarianter såsom hindbær, citron og kokos.', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Gylden rom 25 år Gran Reserva Especial', 'https://www.foetex.dk/produkter/gylden-rom-25-aar-gran-reserva-especial/200147330/', 699, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/1bfff0d2-cc2d-4b0d-9bde-dbb14bbec232', '<b>Alkohol</b>: 40%<br><b>Indhold</b>: 70 cl.<br><b>Land</b>: Guatemala<br>&nbsp;<br>Ron Zacapa&nbsp;har siden slutningen af halvfjerdserne produceret deres verdensberømte rom og den&nbsp;er måske den mest kendte premium rom i verden.<br>Ron Zacapa bruger ikke melasse som 90% af rom industrien gør. Derimod har de deres egne sukkerrørsmarker, hvor de anvender den dyrere rørsukker honning, som indeholder meget mere sukker. Hvilket er en væsentlig årsag til, at Ron Zacapa er en sødere rom end sine konkurrenter.<br>Ron Zacapa Centenario XO er kronjuvelen i Zacapa rom serien. Lavet på juicen fra jomfru sukkerrør, og lagret i 23 år i Soleraen i 2300 meters højde i Guatemala, for til sidst at få en unik 2 årig fadlagring på gamle franske cognacfade.<br>Den store forskel mellem Ron Zacapa 23 års og denne 25 års Ron Zacapa XO er de 2 år XO''en er lagret ekstra. Det giver meget mere "kant" og flere nuancer i smagen.<br>Duften er kompleks med noter af bl.a. læder og en sødlig røg.<br>Smagen af fad trænger tydeligt i gennem, men også noter af karamel og et sødligt strejf af vanille.&nbsp;Eftersmagen er lang og meget behagelig.<br>', '2026-11-08 10:00:00+01');
INSERT INTO stg_foetex_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bacardi Gylden rom 8 år Reserva', 'https://www.foetex.dk/produkter/gylden-rom-8-aar-reserva/100533674/', 270, FALSE, 70, 40, 'https://digitalassets.sallinggroup.com/image/upload/e_trim/b_white,c_pad,e_sharpen:80,f_auto,q_auto,w_464,h_464/c6c3264c9bacc9bec63ece40046e2380', 'En fløjlsblød og fyldig gylden spiritus med træk af krydret karamel, egetræ, muskat og abrikos.<br>Kan nydes ren både med eller uden en isterning.<br><br><h2>Om Bacardi</h2><br>Bacardi-familien har produceret spiritus siden 1862, hvor grundlæggeren Don Facundo Bacardi brugte over 10 år på at fremstille den perfekte Bacardi Carta Blanca. I dag tilbyder virksomheden et bredt udvalg af velsmagende spiritus i mange forfriskende smagsvarianter såsom hindbær, citron og kokos.', '2026-11-08 10:00:00+01');
